//! Safe, local generation and execution of a small GitHub Actions CI surface.
//!
//! The scanner reads repository metadata only. It never evaluates a build file,
//! package manifest, hook, or project command. Commands are drafted into
//! `.github/ci/project.toml`; the checked-in configuration is the runtime
//! source of truth after generation.

use std::collections::{BTreeMap, BTreeSet};
use std::env;
use std::ffi::OsString;
use std::fmt::Write as _;
use std::fs;
use std::io::{self, IsTerminal, Read as _, Write as _};
use std::path::{Component, Path, PathBuf};
use std::process::{Command, Stdio};
use std::time::{SystemTime, UNIX_EPOCH};

use clap::{Parser, ValueEnum};
use serde::Serialize;
use serde_yaml::Value;

mod config;
mod estate;
mod primitives;
mod runners;
mod runtime;
mod scan;
mod tui;

use crate::primitives::{WorkflowIr, WorkflowKind};
use crate::scan::file_walk::is_test_support_path;

/// Revision of the generator's rendering contract.
///
/// Any change that can alter generated bytes for an unchanged scan and an
/// unchanged repository config must bump this revision, so recorded generator
/// state can prove which revision produced the recorded outputs. Never reset
/// or reuse a revision.
pub const GENERATOR_REVISION: &str = "44";

const GENERATED_HEADER: &str = "# Generated by velnor-workflow. Regenerate; do not hand-edit.\n";

/// The workflow file that carries the canonical fleet-consumer caller: its
/// bytes are hash-pinned by the released `velnor-actions` reusable it calls,
/// so the generator preserves the render-consumer header instead of stamping
/// its own. The header flips only together with the fleet pins, at a fleet
/// release that expects the new bytes.
const FLEET_CALLER_WORKFLOW: &str = "ci.yml";
const FLEET_CALLER_HEADER: &str = "# Generated by velnor-actions-generator. DO NOT EDIT.\n";

const WORKFLOW_TEMPLATE_DIR: &str = ".github/ci/workflow-templates";
/// The workflow file the per-owner-block update-channel matrix renders into.
const PACKAGE_UPDATE_WORKFLOW: &str = "package-update.yml";
/// The workflow file a declared release publisher renders into.
pub(crate) const RELEASE_WORKFLOW: &str = "release.yml";
/// The consumer-side updater the granted channels are implemented by.
const PACKAGE_UPDATER_WORKFLOW: &str = "package-updater.yml";
// Keep the sidecar path stable so Velnor can adopt repositories generated by
// the former standalone tool without losing overwrite ownership proof.
const OWNERSHIP_STATE: &str = ".github/ci/.github-actions-generator-state";
const OWNERSHIP_STATE_HEADER: &str = "# Generated ownership state; do not edit.\n";
// Schema 2 adds the generation inputs (`config`, `scan`, `generator`) beside
// the recorded outputs. The older layout is never parsed; see
// `parse_ownership_state` for the fail-closed migration rule.
const OWNERSHIP_STATE_SCHEMA: &str = "2";
const OPEN_TOFU_VERSION: &str = "1.12.6";
pub(crate) const VELNOR_WORKFLOW_SETUP_ACTION: &str =
    "tailrocks/velnor/.github/actions/setup-velnor-workflow";
const VELNOR_WORKFLOW_INSTALL_GIT_URL: &str = "https://github.com/tailrocks/velnor";
// The pinned revision of the policy-enforcing runtime binary. It is the single
// literal inside the inline policy job: the `cargo install --rev` pin, the Mr.
// Boxington cache-key suffix, and the `VELNOR_WORKFLOW_POLICY_REVISION` value
// the installed audit binary requires all render from it, so the runtime that
// audits a tree is always exactly the runtime the tree declares. Pin to a
// revision whose `velnor-workflow` binary enforces the inline policy shape;
// advance it atomically with validator changes and immediately after the
// transport change merges — `cargo install --rev` reaches any public SHA, so
// the pin must move in the direct follow-up commit, not wait for a later PR.
//
// This revision is the direct ancestor carrying the validator change for the
// inline Velnor policy shape. Keep the pin paired with that validator contract;
// advancing either side alone makes generated policy jobs fail closed.
pub(crate) const VELNOR_POLICY_WORKFLOW_REV: &str = "643f33123abe01adee09662a366cb9a5d2b3c3bf";
const VELNOR_POLICY_REVISION_ENV: &str = "VELNOR_WORKFLOW_POLICY_REVISION";
// Keep hosted-runner bootstrap reproducible. `uses:` always interpolates this
// literal: GitHub Actions rejects expressions in `uses:` versions (HTTP 422).
// The pin carries the hermetic source bootstrap (build outside the caller
// checkout without caller-inherited flags) and the CONTROLLED_BOOTSTRAP gate
// for default-branch push/schedule/`workflow_dispatch` plus same-repository
// PRs; anything older fails dispatch/schedule planning or poisons macOS
// builds with the Linux mold link arg. Bump after publishing a Velnor commit
// that changes the workflow runtime contract.
const VELNOR_WORKFLOW_SOURCE_REV: &str = "643f33123abe01adee09662a366cb9a5d2b3c3bf";
const MR_BOXINGTON_VERSION: &str = "1.11.1";
const MOLD_VERSION: &str = "2.42.0";
const MOLD_X86_64_SHA256: &str = "f5ed2f6e31d1ada4f07fe766fe0de7a73104d1c5cdc59086fcecc16a43720b6d";
const MOLD_AARCH64_SHA256: &str =
    "3c9a0a3624aac8a2007569ae50c33b3129a0f0ae8bcc974aeee2f8939d295190";
const MR_BOXINGTON_ENABLED_ENV: &str = "VELNOR_WORKFLOW_MBX";
const MR_BOXINGTON_CARGO_SUBCOMMANDS: &[&str] = &[
    "audit", "bench", "build", "check", "clippy", "deb", "deny", "doc", "fix", "fmt", "nextest",
    "package", "publish", "run", "test", "update", "zigbuild",
];
const VELNOR_RELEASE_PACKAGE_SIGNER_TEMPLATE: &str =
    include_str!("../templates/release-package-signer.yml");

