    #[test]
    fn hosted_runtime_setup_uses_the_versioned_setup_action() {
        assert_eq!(VELNOR_POLICY_WORKFLOW_REV, VELNOR_WORKFLOW_SOURCE_REV);
        let config = must(
            scan_repository_with_default_branch(&fixture_root(), RunnerMode::Github, "main"),
            "scan fixture for hosted runtime setup",
        );
        let workflow = WorkflowIr::from_config(&config).render(WorkflowKind::Main);
        let plan = yaml_job(&workflow, "plan");
        let uses_line = setup_action_uses_line(plan);
        assert!(
            uses_line.contains(&format!("@{VELNOR_WORKFLOW_SOURCE_REV}")),
            "Planning uses the SOURCE_REV pin: {uses_line}"
        );
        assert!(
            !uses_line.contains("github.sha"),
            "GitHub Actions forbids expressions in uses: versions: {uses_line}"
        );
        assert!(
            plan.contains(&format!("rev: {VELNOR_WORKFLOW_SOURCE_REV}")),
            "foreign repos install the published pin: {plan}"
        );
        assert!(
            !plan.contains(&format!("rev: {}", github_expression("github.sha"))),
            "foreign Planning must not cargo-install a foreign github.sha: {plan}"
        );
        assert!(
            !plan.contains(&format!(
                "uses: {VELNOR_WORKFLOW_SETUP_ACTION}@{}",
                github_expression("github.sha")
            )),
            "CI Planning must not resolve setup at HEAD: {plan}"
        );
        let mut home = config.clone();
        home.repository = workflow_setup_action_repository().to_owned();
        let home_workflow = WorkflowIr::from_config(&home).render(WorkflowKind::Main);
        let home_plan = yaml_job(&home_workflow, "plan");
        assert!(
            home_plan.contains(&format!(
                "rev: {}",
                workflow_setup_install_rev(workflow_setup_action_repository())
            )),
            "the setup-action owner uses a context-gated HEAD fallback: {home_plan}"
        );
        assert!(workflow.contains("name: Publish Velnor workflow runtime"));
        assert!(workflow.contains("name: Download Velnor workflow runtime"));
        assert!(workflow.contains("name: Verify Velnor workflow runtime"));
        assert!(workflow.contains(".run_id == $run_id"));
        assert!(workflow.contains(".platform == $platform"));
        assert!(workflow.contains("runtime digest mismatch"));
        assert!(workflow.contains("name: velnor-workflow-runtime-"));
        assert!(workflow.contains("${{ runner.os }}-${{ runner.arch }}"));
        assert!(workflow.contains("manifest.json"));
        assert!(!workflow.contains("cargo install --locked --git"));
    }

    #[test]
    fn github_sha_install_rev_keeps_literal_uses_pin() {
        let head_rev = github_expression("github.sha");
        let maintenance = workflow_runtime_setup_with_install_rev(RunnerMode::Github, &head_rev);
        let uses_line = setup_action_uses_line(&maintenance);
        assert!(
            uses_line.contains(&format!("@{VELNOR_WORKFLOW_SOURCE_REV}")),
            "uses: is always SOURCE_REV: {uses_line}"
        );
        assert!(
            !uses_line.contains("github.sha"),
            "GitHub Actions forbids expressions in uses: versions: {uses_line}"
        );
        assert!(
            maintenance.contains(&format!("rev: {head_rev}")),
            "maintenance must install HEAD runtime: {maintenance}"
        );
        let config = must(
            scan_repository_with_default_branch(&fixture_root(), RunnerMode::Github, "main"),
            "scan fixture for Planning install",
        );
        let workflow = WorkflowIr::from_config(&config).render(WorkflowKind::Main);
        let planning = yaml_job(&workflow, "plan");
        assert!(
            planning.contains(&format!(
                "uses: {VELNOR_WORKFLOW_SETUP_ACTION}@{VELNOR_WORKFLOW_SOURCE_REV}"
            )),
            "Planning must pin setup to SOURCE_REV: {planning}"
        );
        assert!(
            planning.contains(&format!("rev: {VELNOR_WORKFLOW_SOURCE_REV}")),
            "foreign Planning installs the published pin: {planning}"
        );
        assert!(
            !planning.contains(&format!("uses: {VELNOR_WORKFLOW_SETUP_ACTION}@{head_rev}")),
            "Planning must not resolve setup at HEAD: {planning}"
        );
        assert!(
            !planning.contains(&format!("rev: {head_rev}")),
            "foreign Planning must not cargo-install a foreign github.sha: {planning}"
        );
        let mut home = config.clone();
        home.repository = workflow_setup_action_repository().to_owned();
        let home_workflow = WorkflowIr::from_config(&home).render(WorkflowKind::Main);
        let home_plan = yaml_job(&home_workflow, "plan");
        assert!(
            home_plan.contains(&format!(
                "rev: {}",
                workflow_setup_install_rev(workflow_setup_action_repository())
            )),
            "the setup-action owner uses a context-gated HEAD fallback: {home_plan}"
        );
        let owned_rev = workflow_setup_install_rev(workflow_setup_action_repository());
        assert!(owned_rev.contains("github.event_name == 'pull_request'"));
        assert!(owned_rev.contains("github.event.repository.default_branch"));
        assert!(owned_rev.contains(VELNOR_WORKFLOW_SOURCE_REV));
        assert_ne!(owned_rev, head_rev);
    }

    #[test]
    fn velnor_runtime_does_not_publish_an_orphan_artifact() {
        let config = must(
            scan_repository_with_default_branch(&fixture_root(), RunnerMode::Velnor, "main"),
            "scan fixture for Velnor runtime handoff",
        );
        let workflow = WorkflowIr::from_config(&config).render(WorkflowKind::Main);
        let plan = yaml_job(&workflow, "plan");
        assert!(
            !plan.contains("name: Set up Velnor workflow runtime"),
            "Velnor Planning must use the image runtime: {plan}"
        );
        assert!(
            !plan.contains("name: Prepare Velnor workflow runtime"),
            "Velnor Planning must not prepare a runtime artifact: {plan}"
        );
        assert!(
            !plan.contains("name: Publish Velnor workflow runtime"),
            "Velnor Planning must not publish a runtime artifact: {plan}"
        );
        assert!(!workflow.contains("name: Download Velnor workflow runtime"));
        assert!(!workflow.contains("  github-"));
        assert!(workflow.contains("  velnor-"));
    }

    #[test]
    fn runtime_lane_consumes_platform_qualified_verified_products() {
        let mut output = String::new();
        WorkflowIr::render_workflow_runtime_download(&mut output, RunnerMode::Github);
        assert!(output.contains(
            &format!(
                "name: velnor-workflow-runtime-{VELNOR_WORKFLOW_SOURCE_REV}-$EYES_OS-$EYES_ARCH"
            )
            .replace("$EYES_OS", "${{ runner.os }}")
            .replace("$EYES_ARCH", "${{ runner.arch }}")
        ));
        assert!(output.contains("GITHUB_RUN_ID"));
        assert!(output.contains(".run_id == $run_id"));
        assert!(output.contains(".revision == $revision"));
        assert!(output.contains(".platform == $platform"));
        assert!(output.contains("runtime digest mismatch"));
        assert!(!output.contains(".head_sha == $revision"));
        assert!(!output.contains(".head_branch == $head_branch"));
        assert!(!output.contains("conclusion == \"success\""));
        assert!(!output.contains("path: ~/.cargo/bin/velnor-workflow\n          if-no-files-found"));

        let publish = workflow_runtime_artifact_upload();
        assert!(publish.contains("name: Prepare Velnor workflow runtime"));
        assert!(publish.contains("manifest.json"));
        assert!(publish.contains("binary_sha256"));
        assert!(publish.contains("head_branch"));
        assert!(publish.contains("${{ runner.os }}-${{ runner.arch }}"));
        assert!(publish.contains("name: Publish Velnor workflow runtime"));
    }

    #[test]
    fn setup_action_bootstrap_allows_same_repository_prs_only() {
        let action = declared_setup_action();
        let bootstrap = must_some(
            action
                .lines()
                .find(|line| line.contains("CONTROLLED_BOOTSTRAP:")),
            "CONTROLLED_BOOTSTRAP expression",
        );
        assert!(action.contains("same-repository PRs may bootstrap"));
        assert!(action.contains(
            "CONTROLLED_BOOTSTRAP: ${{ (github.ref == format('refs/heads/{0}', github.event.repository.default_branch) && (github.event_name == 'push' || github.event_name == 'schedule' || github.event_name == 'workflow_dispatch')) || (github.event_name == 'pull_request' && github.event.pull_request.head.repo.full_name == github.repository) }}"
        ));
        // The runtime build is foreign code: it runs outside the caller
        // checkout and without caller-inherited link flags, which macOS
        // runners cannot link.
        assert!(action.contains("cd \"$RUNNER_TEMP\""));
        assert!(action.contains("-u RUSTFLAGS"));
        assert!(action.contains("-u CARGO_ENCODED_RUSTFLAGS"));
        assert!(
            !bootstrap.contains("github.event_name == 'push' && github.ref =="),
            "CONTROLLED_BOOTSTRAP must gate on ref, not push&&ref: {bootstrap}"
        );
        let expected_source = format!("SOURCE_REPOSITORY: {VELNOR_WORKFLOW_INSTALL_GIT_URL}");
        assert!(action.contains(&expected_source));
        assert!(!action
            .contains("SOURCE_REPOSITORY: ${{ github.server_url }}/${{ github.repository }}"));
        assert!(action.contains("cargo install --locked --git \"$SOURCE_REPOSITORY\""));
        assert!(action.contains("head_sha == env.INSTALL_REV"));
        assert!(action.contains("actions/runs/$artifact_run_id"));
        assert!(action.contains("run_conclusion"));
        assert!(!action.contains(".workflow_run.conclusion == \"success\""));
        assert!(!action.contains("if: steps.cache.outputs.cache-hit != 'true'\n      shell: bash\n      env:\n        INSTALL_REV:"));
        assert!(!action.contains("default-branch-push-only"));
    }

    #[test]
    fn setup_action_forks_cannot_source_bootstrap() {
        let action = declared_setup_action();
        let bootstrap = must_some(
            action
                .lines()
                .find(|line| line.contains("CONTROLLED_BOOTSTRAP:")),
            "CONTROLLED_BOOTSTRAP expression",
        );
        assert!(bootstrap.contains("github.event_name == 'schedule'"));
        assert!(bootstrap.contains("github.event_name == 'workflow_dispatch'"));
        assert!(bootstrap
            .contains("github.event.pull_request.head.repo.full_name == github.repository"));
        assert!(!bootstrap.contains("pull_request_target"));
        assert!(action.contains(
            "source recovery is default-branch push/schedule/workflow_dispatch or same-repository-PR only"
        ));
        assert!(
            !action.contains("source recovery is default-branch-push or same-repository-PR only")
        );
        assert!(!action.contains("pull_request_target"));
    }

    fn declared_setup_action() -> String {
        let action_path = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
            .join("../../.github-gen/sources/actions/setup-velnor-workflow/action.yml");
        must(
            fs::read_to_string(&action_path),
            "read declared setup action",
        )
    }

    #[test]
    fn adopted_templates_refresh_literal_velnor_source_pins_only() {
        let old_revision = "0123456789abcdef0123456789abcdef01234567";
        let template = format!(
            "jobs:\n  checkout:\n    with:\n      repository: {}\n      ref: {old_revision}\n      path: .velnor-source\n    env:\n      VELNOR_SOURCE_SHA: {old_revision}\n  other:\n    with:\n      repository: another/example\n      ref: {old_revision}\n    env:\n      OTHER_SOURCE_SHA: {old_revision}\n",
            crate::regen_repository_marker()
        );

        let rendered = render_static_template(&template);
        assert!(rendered.starts_with(GENERATED_HEADER));
        assert_eq!(rendered.matches(VELNOR_WORKFLOW_SOURCE_REV).count(), 2);
        assert_eq!(rendered.matches(old_revision).count(), 2);
        assert!(rendered.contains("repository: another/example\n      ref: 0123456789"));
        assert!(rendered.contains("OTHER_SOURCE_SHA: 0123456789"));
    }

    #[test]
    fn adopted_templates_refresh_mr_boxington_pins_and_drop_retired_inputs() {
        let old_revision = "0123456789abcdef0123456789abcdef01234567";
        let template = format!(
            "steps:\n  - uses: jdx/mr-boxington-action@{old_revision} # old pin\n    with:\n      backend: github\n      max-size: 20GiB\n      cache-key: fixture\n  - run: echo keep\n"
        );

        let rendered = render_static_template(&template);
        assert!(rendered.contains(ActionPin::MrBoxington.reference()));
        assert!(!rendered.contains(old_revision));
        assert!(!rendered.contains("max-size: 20GiB"));
        assert!(rendered.contains("cache-key: fixture"));
        assert!(rendered.contains("- run: echo keep"));
    }

