    #[test]
    fn cli_accepts_optional_output_path_and_requires_value() {
        let cli = must(
            Cli::parse_args([
                OsString::from("generate"),
                OsString::from("."),
                OsString::from("--output"),
                OsString::from("generated-output"),
            ]),
            "parse output path",
        );
        assert_eq!(cli.output, Some(PathBuf::from("generated-output")));

        let equals = must(
            Cli::parse_args([
                OsString::from("."),
                OsString::from("--output=/tmp/velnor/test1"),
                OsString::from("--runners=velnor"),
            ]),
            "parse equals-form options",
        );
        assert_eq!(equals.output, Some(PathBuf::from("/tmp/velnor/test1")));
        assert_eq!(equals.runners, RunnerMode::Velnor);

        let missing = Cli::parse_args([OsString::from("."), OsString::from("--output")]);
        assert!(missing
            .err()
            .is_some_and(|error| error.to_string().contains("--output")));
    }

    #[test]
    fn clap_provides_help_and_version_diagnostics() {
        let help = must_some(
            parse_raw_clap([OsString::from("--help")]).err(),
            "help must be a display diagnostic",
        );
        assert_eq!(help.kind(), clap::error::ErrorKind::DisplayHelp);
        assert!(help.to_string().contains("[TARGET] [TARGET]"));
        assert!(!help.to_string().contains("<TARGET>..."));
        assert!(help.to_string().contains("generate TARGET"));
        assert!(help.to_string().contains("--output <PATH>"));

        let version = must_some(
            parse_raw_clap([OsString::from("--version")]).err(),
            "version must be a display diagnostic",
        );
        assert_eq!(version.kind(), clap::error::ErrorKind::DisplayVersion);
        assert!(version.to_string().contains(env!("CARGO_PKG_VERSION")));
    }

    #[test]
    fn github_target_parser_accepts_canonical_forms_and_rejects_dot_segments() {
        assert_eq!(
            github_coordinates("example-org/example-repo"),
            Some(("example-org".to_owned(), "example-repo".to_owned()))
        );
        assert_eq!(
            github_coordinates("https://github.com/example-org/.github.git"),
            Some(("example-org".to_owned(), ".github".to_owned()))
        );
        assert!(github_coordinates("../example-repo").is_none());
        assert!(github_coordinates("example-org/..").is_none());
        assert!(github_coordinates("https://github.com/example-org/example-repo/issues").is_none());
    }

