    #[test]
    fn emitted_project_toml_ignores_cache_generation_config() {
        let root = configured_repository(
            "cache-config-runtime-roundtrip",
            Some(
                "schema = 1\n\n[generator]\nrepository = \"example/fixture\"\n\n\
                 [workflow]\nvelnor_labels = [\"self-hosted\", \"fixture-runner\"]\n\n\
                 [cache.github]\nbudget_bytes = 8589934592\n\
                 [cache.velnor]\nbudget_bytes = 53687091200\n",
            ),
        );
        let scanned = must(
            scan_target(&root, RunnerMode::Both, "main"),
            "scan with cache config",
        );
        let emitted = scanned.config.toml();
        assert!(
            !emitted.contains("cache."),
            "project.toml must not carry generator-only cache sections: {emitted}"
        );
        assert!(
            !emitted.contains("budget_bytes"),
            "project.toml must not carry cache budget fields: {emitted}"
        );
        let path = root.join(".github/ci/project.toml");
        must(
            fs::create_dir_all(must_some(path.parent(), "parent")),
            "create runtime config directory",
        );
        must(fs::write(&path, &emitted), "write emitted project.toml");
        must(
            runtime::read_config_for_test(&path),
            "emitted project.toml must round-trip through runtime parser",
        );
        let files = must(generated_files(&scanned.config), "generate");
        assert!(
            files.contains_key(&PathBuf::from("config/fleet/velnor-host.env")),
            "generator must emit velnor-host.env fleet snippet",
        );
        let _ = fs::remove_dir_all(root);
    }

