    #[test]
    fn reviewed_preimages_reject_same_action_concurrent_replacement() {
        let root = temporary_repository("reviewed-preimage-replacement");
        let relative = PathBuf::from(".github/workflows/ci-pr.yml");
        let initial = BTreeMap::from([(
            relative.clone(),
            format!("{GENERATED_HEADER}name: initial\n"),
        )]);
        must(
            write_generated(&root, &initial, false, false, false),
            "write initial generated layout",
        );
        let wanted = BTreeMap::from([(
            relative.clone(),
            format!("{GENERATED_HEADER}name: wanted\n"),
        )]);
        let reviewed = must(
            plan_generated_write(&root, &wanted, &GenerationInputs::parts(0, 0)),
            "capture reviewed preimages",
        );
        let concurrent = BTreeMap::from([(
            relative.clone(),
            format!("{GENERATED_HEADER}name: concurrent\n"),
        )]);
        must(
            write_generated(&root, &concurrent, false, false, true),
            "write concurrent generated layout",
        );
        let current = must(
            plan_generated_write(&root, &wanted, &GenerationInputs::parts(0, 0)),
            "capture concurrent preimages",
        );
        assert_ne!(reviewed, current);

        let error = must_some(
            apply_generated_write_plan(
                &root,
                &wanted,
                &GenerationInputs::parts(0, 0),
                false,
                false,
                true,
                &reviewed,
            )
            .err(),
            "refuse unreviewed concurrent bytes",
        );
        assert!(error.to_string().contains("changed after preflight"));
        assert_eq!(
            must(
                fs::read_to_string(root.join(relative)),
                "read preserved bytes"
            ),
            concurrent.values().next().cloned().unwrap_or_default()
        );
        let _ = fs::remove_dir_all(root);
    }
