    /// A repository that declares everything about itself: identity, runner
    /// placement, an owned template directory, and the repository-local files
    /// the generated output writes. Nothing in this setup names a repository
    /// the generator knows.
    fn declared_surface_repository(
        name: &str,
        config: &str,
        templates: &[(&str, &str)],
        static_files: &[(&str, &str)],
    ) -> PathBuf {
        let root = temporary_repository(name);
        let git = root.join(".git");
        must(fs::create_dir_all(&git), "create git metadata");
        must(
            fs::write(
                git.join("config"),
                "[remote \"origin\"]\n    url = https://github.com/example/owned.git\n",
            ),
            "write origin remote",
        );
        must(
            fs::write(root.join("README.md"), "# owned\n"),
            "write markdown surface",
        );
        must(
            fs::create_dir_all(root.join(".github-gen").join("generated-templates")),
            "create the declared template directory",
        );
        for (file, body) in templates {
            let path = root
                .join(".github-gen")
                .join("generated-templates")
                .join(file);
            must(
                fs::create_dir_all(path.parent().unwrap_or(&path)),
                "create template parent",
            );
            must(fs::write(&path, body), "write declared template");
        }
        for (file, body) in static_files {
            let path = root.join(".github-gen").join("sources").join(file);
            must(
                fs::create_dir_all(path.parent().unwrap_or(&path)),
                "create source parent",
            );
            must(fs::write(&path, body), "write declared source");
        }
        must(
            fs::create_dir_all(root.join(".github-gen")),
            "create the generation input directory",
        );
        must(
            fs::write(root.join(config::GENERATION_CONFIG_PATH), config),
            "write the generation config",
        );
        root
    }

    const DECLARED_SURFACE_CONFIG: &str = "schema = 1\n\n\
         [generator]\n\
         repository = \"example/owned\"\n\n\
         [workflow]\n\
         github_runner = \"ubuntu-26.04\"\n\
         velnor_labels = [\"self-hosted\", \"example-lane\"]\n\
         profile = \"example-profile\"\n";

    const DECLARED_SURFACE_TEMPLATE: &str =
        "# Generated by velnor-workflow. Regenerate; do not hand-edit.\n\
         name: Owned surface\n\n\
         on:\n\
           push:\n\
             branches: [main]\n\n\
         permissions:\n\
           contents: read\n\n\
         jobs:\n\
           verify:\n\
             runs-on: [self-hosted, example-lane]\n\
             steps:\n\
               - uses: actions/checkout@v5\n\
               - run: echo owned\n";

    #[test]
    fn declared_templates_own_the_whole_surface() {
        let config = format!(
            "{DECLARED_SURFACE_CONFIG}\n\
             [[static_files]]\n\
             file = \".github/actions/example/action.yml\"\n\
             source = \".github-gen/sources/actions/example/action.yml\"\n"
        );
        let root = declared_surface_repository(
            "declared-surface",
            &config,
            &[("owned.yml", DECLARED_SURFACE_TEMPLATE)],
            &[(
                "actions/example/action.yml",
                "name: 'Example composite'\ndescription: 'Owned verbatim'\nruns:\n  using: composite\n  steps: []\n",
            )],
        );
        let scanned = must(
            scan_target(&root, RunnerMode::Both, "main"),
            "scan the declared surface",
        );
        let config = scanned.config;
        assert!(config.declared_surface);
        assert!(!config.adopted_workflow_surface);
        assert_eq!(config.repository, "example/owned");
        assert_eq!(config.profile, "example-profile");
        assert_eq!(config.velnor_labels, vec!["self-hosted", "example-lane"]);
        assert!(config.workflow_templates.is_empty());
        assert_eq!(config.static_files.len(), 1);

        let files = must(generated_files(&config), "generate");
        assert!(
            files.contains_key(&PathBuf::from(".github/workflows/ci-pr.yml")),
            "GitHub-default surface must include ci-pr.yml"
        );
        assert!(!files.contains_key(&PathBuf::from(".github/workflows/owned.yml")));

        // The declared repository-local file is written verbatim from its
        // declared source.
        let composite = ".github/actions/example/action.yml";
        assert_eq!(
            files.get(Path::new(composite)).map(String::as_str),
            Some("name: 'Example composite'\ndescription: 'Owned verbatim'\nruns:\n  using: composite\n  steps: []\n"),
            "declared static file missing from generated output"
        );
        let project = must_some(
            files.get(&PathBuf::from(".github/ci/project.toml")),
            "generated project config",
        );
        assert!(project.contains("repository = \"example/owned\""));
        assert!(project.contains("profile = \"example-profile\""));
        assert!(project.contains("velnor_labels = [\"self-hosted\", \"example-lane\"]"));
        assert!(project.contains("github_runner = \"ubuntu-26.04\""));
        let _ = fs::remove_dir_all(root);
    }

    #[test]
    fn declared_surface_rewrite_after_wipe_is_byte_identical() {
        let root = declared_surface_repository(
            "declared-surface-wipe",
            DECLARED_SURFACE_CONFIG,
            &[("owned.yml", DECLARED_SURFACE_TEMPLATE)],
            &[(
                "actions/example/action.yml",
                "name: 'Example composite'\ndescription: 'Owned verbatim'\nruns:\n  using: composite\n  steps: []\n",
            )],
        );
        let config = must(
            scan_repository(&root, RunnerMode::Both),
            "scan the declared surface",
        );
        let files = must(generated_files(&config), "generate");
        must(
            write_generated(&root, &files, false, false, false),
            "generate the declared surface",
        );
        must(
            fs::remove_dir_all(root.join(".github")),
            "wipe the generated surface",
        );
        let rescan = must(
            scan_repository(&root, RunnerMode::Both),
            "rescan the wiped surface",
        );
        let regenerated = must(generated_files(&rescan), "generate");
        assert_eq!(
            regenerated, files,
            "a wiped declared surface must regenerate byte for byte"
        );
        must(
            write_generated(&root, &regenerated, false, false, false),
            "regenerate the wiped surface",
        );
        for path in regenerated.keys() {
            assert!(
                root.join(path).is_file(),
                "missing regenerated file: {}",
                path.display()
            );
        }
        assert!(root.join(OWNERSHIP_STATE).is_file());
        let _ = fs::remove_dir_all(root);
    }

